
# =====================================================================
# THE CELLS OF CHAPTER 22 — F1 the lost thing (22:1-4), F2 the garments, the nest, the parapet, the mixtures and the tassels (22:5-12); F3 the slandered bride (22:13-21), F4 the adulterer, the betrothed girl and the seducer (22:22-29) — each ask a case; the verdicts DATA rows or PARAMETERS
# =====================================================================
def the_lost_thing(case, data):
    """F1 — Deut 22:1-4 — ONE LINE lost_thing_declared writing lost_thing_return_commanded and fallen_beast_raising_commanded (STATUSES) and hiding_from_lost_thing_barred (a BLOCK); Exodus 23:4-5's cells by CALL (ordinances — the Exodus runner READ THESE VERSES FORWARD: 'Deut 22:1-4 restates [IMPORT]'); the cases the answer sheet's finders — Bava Metzia 2:7-10 the exam rows"""
    del P_[:]
    ask = case['ask']
    if ask == 'your_brothers_ox_or_sheep_straying':
        ink('22:1', "'YOU SHALL NOT SEE YOUR BROTHER'S OX OR HIS SHEEP STRAYING AND HIDE YOURSELF FROM THEM: RETURN, YOU SHALL RETURN THEM TO YOUR BROTHER' — the doubled verb (the seven infinitive absolutes of the four chapters, 22:1 the first); 22:1 shares %d tokens in order with 22:4 and %d with Exodus 23:4 (the reading's twins); the closest kin %s" % (TWIN['22:1 vs 22:4'], TWIN['22:1 vs Exod 23:4'], KINC[(22, 1)][0]))
        move("the Sifrei 222:1-8 (read whole at the reading — the headless piska opening on Exodus 23:5's fallen ass); cold_run_ordinances (CALL) — OR.courts(enemy_ox) = %s, OR.courts(straying) = %s, OR.courts(return_doubled) = %s" % (OR_OX[0], OR_STRAY[0], OR_RET2[0]), "'YOU SHALL NOT SEE' a negative commandment, 'when you meet' (Exodus 23:4) a positive — the two seats one law (222:4); 'your brother's' — and your enemy's from Exodus 23:4, any owner (222:5); 'straying' — outside the boundary, in the manner of their straying (222:6; the Exodus cell's 'outside_the_boundary' by CALL); 'RETURN, you shall return' — returned and it fled, even four and five times (222:8; the Exodus cell's 'even_four_and_five_times' reads THIS verse: 'Deut 22:1' in its own why)")
        dat("THE WRITE lost_thing_return_commanded — a STATUS on israel_people at the chapters' own day (DK2); the Exodus registrations restores and unloading_owed the references (SCANS: restores %s) — never a second write; the exam's person the finder whose returned ox fled five times — bound to return it the sixth" % (SCANS['restores'],))
        return out("your brother's ox or sheep straying (22:1) — the negative beside Exodus 23:4's positive, any owner's, outside the boundary; returned and it fled even five times, RETURN you shall return (the Sifrei 222:1-8; ordinances' %s, %s and %s by CALL): THE WRITE lost_thing_return_commanded, a STATUS on Israel at the chapters' own day; the finder whose ox fled five times bound the sixth" % (OR_OX[0], OR_STRAY[0], OR_RET2[0]), ['lost_thing_return_commanded'])
    if ask == 'what_is_a_lost_thing':
        ink('22:1', "'STRAYING' — in the manner of their straying: MISHNAH BAVA METZIA 2:9 CITED IN THE SPINE'S OWN HEBREW at 222:6 (the exam row read whole)")
        move("the Sifrei 222:6 = Mishnah Bava Metzia 2:9 (the exam row, read whole)", "WHAT IS A LOST THING? he found an ass or a cow grazing by the way — not a lost thing; an ass with its gear overturned, a cow running among the vineyards — a lost thing; returned it and it fled, returned it and it fled, even four and five times — bound to return it; the idle finder's wage — as an idle laborer; if there is a court he stipulates before it; if there is no court before whom shall he stipulate? his own comes first (Bava Metzia 2:9)")
        dat("THE PARAMETER the_finders_wage (an idle laborer's — Bava Metzia 2:9; the court's stipulation the exit); the exam's person the finder of a cow grazing by the way — accepted as no finder at all, the cow no lost thing")
        return out("what is a lost thing (22:1) — grazing by the way none, gear overturned or running among the vineyards a lost thing; the finder's wage an idle laborer's, the stipulation before the court (Mishnah Bava Metzia 2:9 in the spine's own Hebrew at 222:6): the finder of a grazing cow accepted, no lost thing in his hand", ['accepted'])
    if ask == 'until_your_brother_seeks_it':
        ink('22:2', "'and if your brother is not near you, or you know him not, you shall gather it into your house, and it shall be with you UNTIL YOUR BROTHER SEEKS IT, and you shall return it to him' — the seeking the claimant's; the closest kin %s" % (KINC[(22, 2)][0],))
        move("the Sifrei 223:1-4 (read whole at the reading); MISHNAH BAVA METZIA 2:7 (the exam row, read whole); cold_run_ordinances (CALL) — OR.courts(deceiver) = %s" % (OR_DECEIVER[0],), "'UNTIL YOUR BROTHER SEEKS IT' — could you give it to him before he seeks it? rather: until you examine your brother, whether he is a deceiver or not (223:2 — Bava Metzia 2:7: he told the lost thing but not its signs, not given; the deceiver even with the signs not given, 'until you examine your brother whether he is a deceiver'); what works and eats — works and eats; what does not work and eats — sold; the money's use — R. Tarfon he may use it, R. Akiva he may not (2:7's two arms)")
        dat("THE PARAMETER the_lost_moneys_use (Bava Metzia 2:7 — R. Tarfon and R. Akiva TWO ARMS, the sheet's dispute carried); the exam's person the claimant with the signs but a deceiver's name — not given until examined")
        return out("until your brother seeks it (22:2) — until you examine the claimant: the signs given, the deceiver refused even with them; what works and eats works and eats; the money's use R. Tarfon's and R. Akiva's two arms (the Sifrei 223:1-4; Mishnah Bava Metzia 2:7; ordinances' %s by CALL): the claimant with the signs and a deceiver's name refused until examined" % (OR_DECEIVER[0],), ['accepted'])
    if ask == 'the_lost_things_keeping':
        ink('22:3', "'and so shall you do with his ass, and so with his garment, and so with EVERY LOST THING of your brother which is lost from him and you have found' — the garment the general's particular (Exodus 23:4's ox and ass, this verse's garment and every thing)")
        move("MISHNAH BAVA METZIA 2:8 (the exam row, read whole); the Sifrei 224:1-4", "he found scrolls — reads them once in thirty days; if he cannot read he rolls them; he shall not learn from them a first time nor read a portion and translate it; a garment — shakes it once in thirty days and spreads it for its need, not for his honor; vessels of silver and copper — uses them for their need, not to wear them out; vessels of gold and glass — he shall not touch them until Elijah comes; found a sack or a basket or anything not his way to take — he does not take (Bava Metzia 2:8)")
        dat("the_lost_things_keeping a DATA row of the clocks (the scrolls once in thirty days, the garment once in thirty days, the gold and the glass untouched until Elijah comes — Bava Metzia 2:8); the exam's person the finder who wears the found garment for his honor — barred from it")
        return out("the lost thing's keeping (22:3) — scrolls read once in thirty days, the garment shaken and spread for its need, silver and copper used for their need, gold and glass untouched until Elijah comes; what is not his way to take he does not take (Mishnah Bava Metzia 2:8; the Sifrei 224:1-4): the finder who wears the garment for his honor barred from it", ['accepted'])
    if ask == 'you_may_not_hide':
        ink('22:3', "'YOU MAY NOT HIDE YOURSELF' — the negative at 22:3 and 'and hide yourself' at 22:1 and 22:4: the hiding three times in four verses (the negations %s at 22:1-4)" % ({'%d:%d' % k: len(NEG[k]) for k in NEG if k[0] == 22 and k[1] <= 4},))
        move("the Sifrei 222:7, 224:1-4 (read whole at the reading); MISHNAH BAVA METZIA 2:10 (the exam row, read whole); cold_run_ordinances (CALL) — OR.courts(father_says_no) = %s" % (OR_FATHER[0],), "'AND HIDE YOURSELF FROM THEM' — sometimes you hide and sometimes you do not: a priest and it is in a graveyard, an elder and it is beneath his dignity, his own work greater than his fellow's — 'you may not hide' the rest (222:7, 224:2-3); found it in the stable — no duty; in the public domain — the duty (Bava Metzia 2:10); his father said to him 'defile yourself' or 'do not return' — he does not listen to him (2:10; the Exodus cell's 'do_not_listen' by CALL)")
        dat("THE WRITE hiding_from_lost_thing_barred — a BLOCK on israel_people at the chapters' own day (DK2); the_hiding a DATA row of the exemptions (the priest in the graveyard, the elder beneath his dignity, his own greater loss — Bava Metzia 2:10 with the Sifrei 224); the exam's person the elder who passes the lost sack beneath his dignity — exempt, the hiding permitted him")
        return out("you may not hide (22:3) — the hiding barred, with its exemptions: the priest in the graveyard, the elder beneath his dignity, his own loss greater; the stable no duty, the public domain the duty; his father's 'do not return' unheeded (the Sifrei 222:7, 224:1-4; Mishnah Bava Metzia 2:10; ordinances' %s by CALL): THE WRITE hiding_from_lost_thing_barred, a BLOCK on Israel at the chapters' own day; the elder beneath his dignity exempt" % (OR_FATHER[0],), ['hiding_from_lost_thing_barred'])
    if ask == 'his_ass_or_his_ox_fallen':
        ink('22:4', "'YOU SHALL NOT SEE YOUR BROTHER'S ASS OR HIS OX FALLEN IN THE WAY AND HIDE YOURSELF FROM THEM: RAISE, YOU SHALL RAISE WITH HIM' — the second doubled verb; 22:4 shares %d tokens with Exodus 23:5 (the reading's twin: 'fallen in the way' this verse's, 'lying under its burden' the Exodus's)" % (TWIN['22:4 vs Exod 23:5'],))
        move("the Sifrei 222:1-3, 225:1-4, 226:1-3 (read whole at the reading); MISHNAH BAVA METZIA 2:10 (the exam row); MISHNAH BAVA KAMMA 5:7 by the Exodus cell; cold_run_ordinances (CALL) — OR.courts(with_him) = %s, OR.courts(unload_load) = %s, OR.courts(measure) = %s, OR.courts(common_case_animals) = %s, OR.courts(ris) = %s" % (OR_WITH[0], OR_UNLOAD[0], OR_MEASURE[0], OR_COMMON[0], OR_RIS[0]), "'FALLEN IN THE WAY' — and not in the stable (225:1); 'with him' — the owner who went and sat, 'since the duty is on you, raise if you wish' — exempt; old or sick — bound (225:3-4; Bava Metzia 2:10's 'owner_idle_exempts'); 'release with him' (Exodus 23:5) unloading, 'raise with him' (22:4) loading — R. Judah b. Beteira splits the verses (222:3; the Exodus cell: unloading a Torah duty, loading disputed, a load it can bear); 'ox or ass' name the common case — every beast (Bava Kamma 5:7 by CALL); the ris the duty's distance, one in seven and a half of a mil (the Exodus cell's DATA)")
        dat("THE WRITE fallen_beast_raising_commanded — a STATUS on israel_people at the chapters' own day (DK2); the kin's effects restores and unloading_owed the tape's Exodus registrations, never a second write (SCANS: unloading_owed %s); the exam's person the owner who sits idle and says 'raise if you wish' — the passerby exempt" % (SCANS['unloading_owed'],))
        return out("his ass or his ox fallen (22:4) — in the way, not in the stable; RAISE you shall raise WITH HIM: the idle owner exempts, the old and the sick oblige; unloading a Torah duty and loading its twin; every beast by the common case; the ris the distance (the Sifrei 222:1-3, 225:1-226:3; Mishnah Bava Metzia 2:10; ordinances' %s, %s and %s by CALL): THE WRITE fallen_beast_raising_commanded, a STATUS on Israel at the chapters' own day; the passerby before the idle owner exempt" % (OR_WITH[0], OR_UNLOAD[0], OR_RIS[0]), ['fallen_beast_raising_commanded'])
    return 'no verdict in span', [], list(P_)


def the_garments_nest_parapet_and_mixtures(case, data):
    """F2 — Deut 22:5-12 — TWO LINES: garments_nest_parapet_declared (22:5-8) writing cross_dressing_barred and house_bloodguilt_barred (BLOCKS), mother_bird_sending_commanded and parapet_commanded (STATUSES); mixtures_tassels_declared (22:9-12) writing vineyard_mixed_seed_barred, ox_ass_plowing_barred and wool_linen_barred (BLOCKS) and tassels_commanded (a STATUS); Leviticus 19:19's cells by CALL (holiness_b — the mixtures ROUTED here at their own compile), the abomination formula by CALL (seven_nations), the reward clause and the Sabbath's pair by CALL (covenant_at_horeb), the seven that surround a man by CALL (hear_o_israel); Chullin 12:2-3 the exam rows"""
    del P_[:]
    ask = case['ask']
    if ask == 'a_mans_gear_on_a_woman':
        ink('22:5', "'A MAN'S GEAR SHALL NOT BE ON A WOMAN, and a man shall not put on a woman's garment, for AN ABOMINATION TO THE LORD YOUR GOD is everyone who does these' — the Name's ONE seat in chapter 22 (%s); the abomination formula's seats in the Torah %s (this the fifth), 'everyone who does these' at %s" % ([v for v in range(1, 30) if any('יהוה' in x for x in W22(v))], P('תועבת', 'יהוה', books=T), P('כל', 'עשה', 'אלה', books=T)))
        move("the Sifrei 226:4-7 (read whole at the reading); Onkelos 22:5 'the armament of a man'; cold_run_seven_nations (CALL) — SN.the_images_and_the_devoted(abomination_to_the_lord) = %s" % (SN_ABOM[1],), "'A MAN'S GEAR' — Onkelos 'the ARMAMENT of a man shall not be on a woman': the woman not to go out to war with weapons; 'a man shall not put on a woman's garment' — not to adorn himself with a woman's adornments (226:4-6 — the reading's find 15: the two readings, the arms and the adornment); 'an abomination' — the formula's fifth seat, 7:25's the first (seven_nations by CALL — the book's phrase)")
        dat("THE WRITE cross_dressing_barred — a BLOCK on israel_people at the chapters' own day (DK2); the_gears_two_readings a DATA row (the arms by Onkelos, the adornment by the spine); house_abomination_barred 7:26's the tape's reference (SCANS %s); the exam's person the woman who goes out armed to war — barred from it" % (SCANS['house_abomination_barred'],))
        return out("a man's gear on a woman (22:5) — the armament of a man not on a woman, a woman's adornment not on a man; an abomination — the formula's fifth seat (the Sifrei 226:4-7; Onkelos; seven_nations' %s by CALL): THE WRITE cross_dressing_barred, a BLOCK on Israel at the chapters' own day; the woman armed for war barred from it" % (SN_ABOM[1][0],), ['cross_dressing_barred'])
    if ask == 'the_nest_before_you':
        ink('22:6-7', "'When a bird's nest CHANCES BEFORE YOU in the way, in any tree or on the ground, fledglings or eggs, and the mother sitting on the fledglings or on the eggs, YOU SHALL NOT TAKE THE MOTHER WITH THE YOUNG: SEND, YOU SHALL SEND THE MOTHER, and the young you may take for yourself' — the third doubled verb (22:7); the closest kin %s" % (KINC[(22, 6)][0],))
        move("the Sifrei 227:1-11, 228:1-8 (read whole at the reading); MISHNAH CHULLIN 12:3 (the exam row, read whole)", "'CHANCES' — excluding the prepared (227:1); 'in the way, in any tree or on the ground' — the tied birds in another's domain excluded (228:4); 'the mother SITTING' — hovering, her wings touching the nest — bound; not touching — exempt (Chullin 12:3); 'fledglings or eggs' — as fledglings are viable so eggs, the addled excluded; the least two, even one (228:3); 'you shall not take the mother with the young' — took the mother, the young sent; 'SEND, you shall send' — sent her and she returned, even four and five times, bound (Chullin 12:3: 'send, you shall send'); he who says 'I will take the mother and send the young' — bound to send the mother; took the young and returned them to the nest and the mother returned upon them — exempt (12:3)")
        dat("THE WRITE mother_bird_sending_commanded — a STATUS on israel_people at the chapters' own day (DK2); the_nests_sending a DATA row (the hovering mother, the one fledgling, the return even five times — Chullin 12:3); the exam's person the finder who took the mother and let the young go — bound to send the mother still")
        return out("the nest before you (22:6-7) — the chance nest, not the prepared; the mother hovering with her wings on the nest; even one fledgling or one egg; SEND you shall send — even four and five times; the mother taken and the young sent, the mother still owed (the Sifrei 227:1-228:8; Mishnah Chullin 12:3): THE WRITE mother_bird_sending_commanded, a STATUS on Israel at the chapters' own day; the finder who took the mother bound to send her still", ['mother_bird_sending_commanded'])
    if ask == 'the_nests_kinds':
        ink('22:6', "'a BIRD'S nest' — the kind unnamed in the ink: the answer sheet's parameter (Chullin 12:2 the exam row)")
        move("MISHNAH CHULLIN 12:2 (the exam row, read whole); the Sifrei 227:5-6", "an unclean bird — exempt from sending; an unclean bird sitting on the eggs of a clean bird, or a clean bird on the eggs of an unclean — exempt; a male partridge — R. Eliezer binds, the sages exempt (Chullin 12:2 — TWO ARMS: the male pheasant that sits on eggs); the clean bird alone the law's (227:5)")
        dat("THE PARAMETER the_nests_kinds (Chullin 12:2 — the clean bird bound, the unclean exempt, the male pheasant R. Eliezer's and the sages' two arms); the exam's person the finder of an unclean bird on clean eggs — exempt")
        return out("the nest's kinds (22:6) — a clean bird bound, an unclean exempt, the unclean on the clean's eggs exempt, the male pheasant disputed (Mishnah Chullin 12:2; the Sifrei 227:5-6): the finder of an unclean bird on clean eggs exempt", ['accepted'])
    if ask == 'the_mother_taker_and_the_reward':
        ink('22:7', "'that IT MAY BE WELL WITH YOU AND YOU PROLONG YOUR DAYS' — the reward clause the tape's own (5:16's honor of parents: 22:7 shares %d tokens in order with 5:16 — the reading's twin); the Sifrei 228:8's Mishnah by abbreviation, the English supplying Makkot 3:4" % (TWIN['22:7 vs 5:16'],))
        move("the Sifrei 228:5-8 (read whole at the reading; 228:5 REREAD from chapter 14); Makkot 3:4 by the English; cold_run_covenant_at_horeb (CALL) — CH.DATA[the_reward_clause] read", "'that it may be well with you and you prolong your days' — the honor of parents' clause said of the lightest commandment (228:6: if the sending of the nest, worth an issar, is rewarded with long days, how much more the weighty); the taker of the mother upon the young — R. Judah: he is flogged and does not send; the sages: he sends and is not flogged — a negative commandment made good by a positive is not flogged (228:8 — Makkot 3:4 by the English, TWO ARMS); blessings_for_hearing TWO on israel_people THE TAPE'S REFERENCE (SCANS %s), no write" % (SCANS['blessings_for_hearing'],))
        dat("THE PARAMETER the_mother_takers_sanction (Makkot 3:4 — R. Judah's lashes and the sages' sending, two arms); the exam's person the taker of the mother who sends her after the taking — the sages' arm, not flogged")
        return out("the mother taker and the reward (22:7) — the lightest commandment with the weightiest clause; the taker of the mother flogged (R. Judah) or sends and is not flogged (the sages) — two arms (the Sifrei 228:5-8; Makkot 3:4 by the English; covenant_at_horeb's reward clause read): the taker who sends after taking not flogged", ['accepted'])
    if ask == 'the_parapet_and_the_blood':
        ink('22:8', "'When you build A NEW HOUSE, you shall make A PARAPET for your roof, and YOU SHALL NOT PUT BLOOD IN YOUR HOUSE, if the faller falls from it' — 'a new house' at %s (20:5's dedicator the twin), 'parapet' at %s alone in the Bible" % (P('בית', 'חדש', books=None), P('מעקה', books=None)))
        move("the Sifrei 229:1-11 (read whole at the reading); Onkelos 22:8; cold_run_refuge_war_family (CALL) — RW.the_priests_speech(the_four_exemptions) = %s (20:5's new house the dedicator's)" % (RW_FOUR[1],), "'a new house' — the builder, the buyer, the heir, the receiver of a gift alike (229:1-2); 'house' — a dwelling: the gatehouse, the portico, the balcony excluded (229:3); 'your roof' — not the synagogue's or the study house's (229:6); the roof ten handbreadths (229:8); 'YOU SHALL NOT PUT BLOOD IN YOUR HOUSE' — the faller was to fall from the six days of creation, yet the house's owner bears it: 'he is a liability of a death sentence' (229:9-10 — Onkelos, the reading's find); the house of four by four shared by nine laws (229:10)")
        dat("THE WRITES parapet_commanded (a STATUS) and house_bloodguilt_barred (a BLOCK) on israel_people at the chapters' own day (DK2); the_roofs_height a DATA row (ten handbreadths — 229:8); the_house_of_four_by_four a DATA row (the parapet, the mezuzah, the leaven, the eruv, the plagues of houses, the levirate house, the war's house, the burglar, the sale — 229:10); the exam's person the heir of a house without a parapet — bound to build it")
        return out("the parapet and the blood (22:8) — the new house of the builder, the buyer, the heir; a dwelling of four by four, the roof ten handbreadths; the faller bears his own fall from creation, yet the owner is liable (the Sifrei 229:1-11; Onkelos 'a liability of a death sentence'): THE WRITES parapet_commanded and house_bloodguilt_barred on Israel at the chapters' own day; the heir bound to build", ['parapet_commanded', 'house_bloodguilt_barred'])
    if ask == 'the_vineyards_two_kinds':
        ink('22:9', "'YOU SHALL NOT SOW YOUR VINEYARD WITH TWO KINDS, lest the fullness be forfeited, the seed which you sow and the produce of the vineyard' — 'two kinds' (kilayim) at %s: Leviticus 19:19's field and this verse's vineyard; 22:9 shares %d tokens with Leviticus 19:19" % (P('כלאים', books=None), TWIN['22:9 vs Lev 19:19']))
        move("the Sifrei 230:1-9 (read whole at the reading); cold_run_holiness_b (CALL) — HB.mixtures(vineyard) = %s" % (HB_VINE[0],), "'your vineyard' — not another's, not outside the land (230:1-2); 'lest the fullness be FORFEITED' — lest it be burned: the sanctification's homograph read as the fire (230:4-6); THE VINEYARD'S MIXTURE IS THIS VERSE'S INSTITUTION — Leviticus 19:19's cell ROUTED it here at its own compile ('routed_Deut_22_9 — the VINEYARD's mixture is Deut 22:9's institution [IMPORT — the Deuteronomy walk]': the bald patch, the perimeter, the espalier, the sanctifying, the benefit ban Kilayim 4-7's — the parameters OWED to the docket); mixture_barred ZERO on the running world (SCANS %s) — the reference, never reused" % (SCANS['mixture_barred'],))
        dat("THE WRITE vineyard_mixed_seed_barred — a BLOCK on israel_people at the chapters' own day (DK2); the_vineyards_mixture routed here (holiness_b's 'routed_Deut_22_9'); the Kilayim parameters OWED to the docket (the lean pass); the exam's person the sower of wheat between his vines — barred, the fullness forfeited")
        return out("the vineyard's two kinds (22:9) — your vineyard, in the land; the fullness forfeited to the fire; THE INSTITUTION'S SEAT, Leviticus 19:19's cell routed here (the Sifrei 230:1-9; holiness_b's %s by CALL): THE WRITE vineyard_mixed_seed_barred, a BLOCK on Israel at the chapters' own day; the sower between his vines barred" % (HB_VINE[0],), ['vineyard_mixed_seed_barred'])
    if ask == 'the_ox_and_the_ass':
        ink('22:10', "'YOU SHALL NOT PLOW WITH AN OX AND AN ASS TOGETHER' — no verse of the Bible shares two of its words (KINC %s — the five orphans of the four chapters); the Sabbath's pair at 5:14 (22:10 shares %d tokens with 5:14)" % (KINC[(22, 10)], TWIN['22:10 vs 5:14']))
        move("the Sifrei 231:1-7 (read whole at the reading); cold_run_holiness_b (CALL) — HB.mixtures(plowing) = %s, HB.mixtures(class_table) read, HB.mixtures(mule_kind) = %s; cold_run_covenant_at_horeb (CALL) — CH.the_first_tablet(the_ox_and_the_ass) = %s" % (HB_PLOW[0], HB_MULE[0], CH_OXASS[1]), "'an ox and an ass' — every two kinds, by the Sabbath's 'your ox and your ass' read as every animal (231:1-3 — Bava Kamma 54b's verbal analogy, covenant_at_horeb's cell by CALL); 'plow' — plowing, drawing, leading, even leading by the voice (231:4-6; the Leviticus cell's 'routed_Deut_22_10' and its class table by CALL: the mule's kind follows its mother — R. Judah)")
        dat("THE WRITE ox_ass_plowing_barred — a BLOCK on israel_people at the chapters' own day (DK2); the_pairs_table the Leviticus cell's DATA read (the wild ox, the dog, the pig, the mule); the exam's person who leads an ox and an ass yoked by his voice — barred")
        return out("the ox and the ass (22:10) — every two kinds by the Sabbath's pair; plowing, drawing, leading — even by the voice; the mule by its mother (the Sifrei 231:1-7; holiness_b's %s and covenant_at_horeb's analogy by CALL): THE WRITE ox_ass_plowing_barred, a BLOCK on Israel at the chapters' own day; the leader of the yoked pair barred" % (HB_PLOW[0],), ['ox_ass_plowing_barred'])
    if ask == 'the_mingled_stuff':
        ink('22:11', "'YOU SHALL NOT WEAR MINGLED STUFF (shaatnez), WOOL AND LINEN TOGETHER' — the word at %s alone in the Bible; TWO piskaot head on 22:11 (232 and 233 — the reading's find: 233 running from the mingled stuff to the Sabbath, the levirate and the tribal inheritance in one utterance)" % (P('שעטנז', books=None),))
